        count() { let n = 0; for (const s of map.values()) n += s.size; return n; },
    } as any;
}
const base = { pointerId: 1, pointerType: "mouse", button: 0 };
// moves: list of [dx, dy] steps, each with a frame in between; then glide frames
function drag(attach: any, moves: [number, number][], frames = 600, wheel = 0) {
    const cam = createArcRotateCamera(0.5, 1.0, 5, { x: 0, y: 0, z: 0 });
    const canvas = fakeCanvas();
    const scene = { _beforeRender: [] as any[] } as unknown as SceneContext;
    const detach = attach(cam, canvas, scene);
    const a0 = cam.alpha, b0 = cam.beta, r0 = cam.radius;
    let x = 100, y = 100;
    canvas.fire("pointerdown", { ...base, clientX: x, clientY: y });
    for (const [dx, dy] of moves) {
        x += dx; y += dy;
        canvas.fire("pointermove", { ...base, clientX: x, clientY: y });
        for (const f of [...scene._beforeRender]) f(16);
    }
    canvas.fire("pointerup", { ...base, clientX: x, clientY: y });
    if (wheel) canvas.fire("wheel", { deltaY: wheel, preventDefault() {} });
    for (let i = 0; i < frames; i++) for (const f of [...scene._beforeRender]) f(16);
    return { dA: cam.alpha - a0, dB: cam.beta - b0, dR: cam.radius - r0, hooks: scene._beforeRender.length, canvas, detach, cam, scene };
}
describe("fast orbit", () => {
    it("big drag ratio exact incl glide", () => {
        const m: [number, number][] = [[40, 30]];
        const d = drag((c: any, k: any, s: any) => attachControl(c, k, s), m);
        const f = drag((c: any, k: any, s: any) => attachFastOrbit(c, k, s), m);
        console.log("big", d.dA, d.dB, f.dA, f.dB, f.dA / d.dA, f.dB / d.dB);
        expect(f.dA / d.dA).toBeCloseTo(2, 10);
        expect(f.dB / d.dB).toBeCloseTo(2, 10);
    });
