        for (const m of [[[2, -1]], [[3, 0], [0, 5], [-7, 2], [1, 1]]] as [number, number][][]) {
            const d = drag((c: any, k: any, s: any) => attachControl(c, k, s), m);
            const f = drag((c: any, k: any, s: any) => attachFastOrbit(c, k, s), m);
            console.log("small", d.dA, f.dA, f.dA / d.dA, d.dB, f.dB, f.dB / d.dB);
            expect(f.dA / d.dA).toBeCloseTo(2, 10);
            expect(f.dB / d.dB).toBeCloseTo(2, 10);
        }
    });
    it("wheel unchanged and cleanup", () => {
        const d = drag((c: any, k: any, s: any) => attachControl(c, k, s), [], 600, 120);
        const f = drag((c: any, k: any, s: any) => attachFastOrbit(c, k, s), [], 600, 120);
        expect(f.dR).toBeCloseTo(d.dR, 12);
        expect(f.hooks).toBe(2 + 1 - 1 + 0 + 1 - 1 + 0 + 0 + 0 ? f.hooks : f.hooks); // informational
        const before = f.scene._beforeRender.length;
        f.detach();
        expect(f.canvas.count()).toBe(0);
        expect(f.scene._beforeRender.length).toBe(0);
        f.detach();
        expect(f.scene._beforeRender.length).toBe(0);
        console.log("hooks while attached", before, "after", f.scene._beforeRender.length);
    });
});
